using System.Globalization;
using System.Text;

namespace Bfii.Navmesh.Diagnostics
{
    /// <summary>
    /// Generates the two OBJ fixtures for the in-game island experiment.
    /// </summary>
    /// <remarks>
    /// The experiment these serve is the one unresolved runtime question in the navigation track:
    /// does BFII recompute island membership when a graph is registered, or does it trust the
    /// stored value? Master plan risk R-06, question 2 in section 12, worker report 08 section 8.2.
    ///
    /// The pair is designed so that exactly one variable differs. Both meshes have the same face
    /// count, the same cell size, the same winding and the same total area, so a difference in bot
    /// behaviour between them cannot be attributed to mesh size, tessellation or orientation. The
    /// only difference is connectivity.
    ///
    /// Both are quad grids on the XZ plane at y = 0, wound so the surface normal points along
    /// positive Y. Vertices are emitted so that adjacent cells share corner positions exactly,
    /// which means the parser welds them into shared edges and the compiler sees real adjacency.
    /// </remarks>
    public static class FixtureMeshes
    {
        /// <summary>Cells along X in each slab of the two-island fixture.</summary>
        public const int SlabColumns = 4;

        /// <summary>Cells along Z in every slab.</summary>
        public const int SlabRows = 4;

        /// <summary>Metres per cell.</summary>
        public const float CellSize = 1f;

        /// <summary>
        /// Empty metres between the two slabs. Six metres is far wider than any step height or
        /// agent radius, so no reasonable link generator could bridge it by accident, and it is
        /// still close enough to keep both slabs in view from one spot.
        /// </summary>
        public const float Gap = 6f;

        /// <summary>
        /// Two disjoint walkable slabs sharing no vertex and no edge. 32 faces, 50 vertices,
        /// 2 connected components.
        /// </summary>
        public static string TwoIsland()
        {
            StringBuilder sb = new StringBuilder();
            AppendHeader(
                sb,
                "two-island.obj",
                "Two disjoint slabs. Correct island numbering gives 2 islands.",
                "Spawn a bot on slab A and order it to slab B: see TWO-ISLAND-TEST.md.");

            int vertexBase = 0;
            vertexBase += AppendSlab(sb, vertexBase, 0f, "slab A");
            AppendSlab(sb, vertexBase, (SlabColumns * CellSize) + Gap, "slab B");

            return sb.ToString();
        }

        /// <summary>
        /// One connected slab of the same face count as the two-island fixture: the control.
        /// 32 faces, 45 vertices, 1 connected component.
        /// </summary>
        public static string OneIsland()
        {
            StringBuilder sb = new StringBuilder();
            AppendHeader(
                sb,
                "one-island.obj",
                "One connected slab with the same face count as two-island.obj. 1 island.",
                "The control. A bot must cross this freely whatever the island question turns out to be.");

            AppendGrid(sb, 0, SlabColumns * 2, SlabRows, 0f, "single slab");
            return sb.ToString();
        }

        private static void AppendHeader(StringBuilder sb, string name, string what, string how)
        {
            sb.Append("# ").Append(name).Append('\n');
            sb.Append("# generated by Bfii.Navmesh (navmesh make-fixture)\n");
            sb.Append("# ").Append(what).Append('\n');
            sb.Append("# ").Append(how).Append('\n');
            sb.Append("# quads on the XZ plane at y = 0, wound so the normal points along +Y\n");
            sb.Append('\n');
        }

        private static int AppendSlab(StringBuilder sb, int vertexBase, float originX, string label) =>
            AppendGrid(sb, vertexBase, SlabColumns, SlabRows, originX, label);

        /// <summary>Emits one grid and returns how many vertices it added.</summary>
        private static int AppendGrid(
            StringBuilder sb, int vertexBase, int columns, int rows, float originX, string label)
        {
            int vertexColumns = columns + 1;
            int vertexRows = rows + 1;

            sb.Append("# ").Append(label).Append(": ").Append(columns).Append('x').Append(rows)
              .Append(" cells from x=").Append(Format(originX))
              .Append(" to x=").Append(Format(originX + (columns * CellSize))).Append('\n');

            for (int r = 0; r < vertexRows; r++)
            {
                for (int c = 0; c < vertexColumns; c++)
                {
                    float x = originX + (c * CellSize);
                    float z = r * CellSize;
                    sb.Append("v ").Append(Format(x)).Append(" 0 ").Append(Format(z)).Append('\n');
                }
            }

            for (int r = 0; r < rows; r++)
            {
                for (int c = 0; c < columns; c++)
                {
                    // OBJ indices are 1-based and absolute across the whole file.
                    int v00 = vertexBase + (r * vertexColumns) + c + 1;
                    int v01 = vertexBase + ((r + 1) * vertexColumns) + c + 1;
                    int v11 = vertexBase + ((r + 1) * vertexColumns) + c + 2;
                    int v10 = vertexBase + (r * vertexColumns) + c + 2;

                    sb.Append("f ").Append(v00).Append(' ').Append(v01).Append(' ')
                      .Append(v11).Append(' ').Append(v10).Append('\n');
                }
            }

            sb.Append('\n');
            return vertexColumns * vertexRows;
        }

        private static string Format(float value) =>
            value.ToString("0.####", CultureInfo.InvariantCulture);
    }
}
